import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate, useLocation } from 'react-router-dom';

// ===== ĐỊNH NGHĨA MENU THEO ROLE =====
// allowedRoles: danh sách role được thấy menu này
// Nếu không có allowedRoles → mọi role đều thấy

const menuItems = [
  {
    id: 'dashboard',
    path: '/',
    icon: '📊',
    label: 'Dashboard',
    // Tất cả role đều thấy
  },
  {
    id: 'users',
    path: '/users',
    icon: '🔐',
    label: 'Quản lý User',
    allowedRoles: ['Admin'],
  },
  {
    id: 'hr',
    icon: '👥',
    label: 'Nhân Sự',
    allowedRoles: ['Admin', 'HR Manager'],
    subItems: [
      { path: '/employees', icon: '👥', label: 'Danh sách Nhân viên' },
      { path: '/departments', icon: '🏢', label: 'Phòng Ban' },
      { path: '/positions', icon: '💼', label: 'Chức Vụ' },
    ],
  },
  {
    id: 'payroll',
    icon: '💰',
    label: 'Bảng Lương',
    allowedRoles: ['Admin', 'Payroll Manager'],
    subItems: [
      { path: '/payroll', icon: '💰', label: 'Bảng Lương Tháng' },
      { path: '/salary-history', icon: '📋', label: 'Lịch Sử Lương' },
    ],
  },
  {
    id: 'attendance',
    icon: '📅',
    label: 'Chấm Công',
    allowedRoles: ['Admin', 'Payroll Manager'],
    subItems: [
      { path: '/attendance', icon: '📅', label: 'Dữ Liệu Chấm Công' },
      { path: '/import-leave', icon: '📤', label: 'Import & Nghỉ Phép' },
    ],
  },
  {
    id: 'reports',
    path: '/reports',
    icon: '📈',
    label: 'Báo Cáo',
    allowedRoles: ['Admin', 'HR Manager', 'Payroll Manager'],
  },
  {
    id: 'alerts',
    path: '/alerts',
    icon: '🔔',
    label: 'Cảnh Báo',
    allowedRoles: ['Admin', 'HR Manager', 'Payroll Manager'],
  },

  // ===== MENU RIÊNG CHO EMPLOYEE =====
  {
    id: 'my-profile',
    path: '/employees/me', // handled by EmployeeProfile
    icon: '👤',
    label: 'Hồ Sơ Của Tôi',
    allowedRoles: ['Employee'],
  },
  {
    id: 'my-salary',
    path: '/salary-history',
    icon: '💵',
    label: 'Lương Của Tôi',
    allowedRoles: ['Employee'],
  },
  {
    id: 'my-leave',
    path: '/import-leave',
    icon: '📝',
    label: 'Xin Nghỉ Phép',
    allowedRoles: ['Employee'],
  },
];

// Badge màu theo role
const roleBadge = {
  'Admin':           { bg: '#fef2f2', color: '#dc2626', icon: '🔴', label: 'Admin' },
  'HR Manager':      { bg: '#f0fdf4', color: '#16a34a', icon: '🟢', label: 'HR Manager' },
  'Payroll Manager': { bg: '#eff6ff', color: '#2563eb', icon: '🔵', label: 'Payroll' },
  'Employee':        { bg: '#fefce8', color: '#ca8a04', icon: '🟡', label: 'Employee' },
};

function DashboardLayout() {
  const navigate = useNavigate();
  const location = useLocation();
  const [alertCount] = useState(3);
  const [expandedMenu, setExpandedMenu] = useState(null);

  // Lấy thông tin user hiện tại
  const userInfo = (() => {
    try {
      const u = localStorage.getItem('user');
      return u ? JSON.parse(u) : null;
    } catch { return null; }
  })();

  const userRole = userInfo?.Role || '';
  const userInitials = userInfo?.FullName
    ? userInfo.FullName.split(' ').map(w => w[0]).slice(-2).join('').toUpperCase()
    : userInfo?.Username?.[0]?.toUpperCase() || 'AD';
  const badge = roleBadge[userRole] || roleBadge['Employee'];

  // Lọc menu theo role
  const visibleMenus = menuItems.filter(item => {
    if (!item.allowedRoles) return true; // không giới hạn → hiện với tất cả
    return item.allowedRoles.includes(userRole);
  });

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  const toggleMenu = (menuId) => {
    setExpandedMenu(expandedMenu === menuId ? null : menuId);
  };

  const getPageTitle = () => {
    const path = location.pathname;
    if (path === '/') return { title: 'Dashboard', sub: 'Tổng quan hệ thống HR & Payroll' };
    if (path === '/users') return { title: 'Quản Lý User', sub: 'Quản lý tài khoản, phân quyền' };
    if (path.startsWith('/employees/add')) return { title: 'Thêm Nhân Viên', sub: 'Tạo hồ sơ nhân viên mới' };
    if (path.startsWith('/employees/edit')) return { title: 'Sửa Nhân Viên', sub: 'Cập nhật thông tin nhân viên' };
    if (path.startsWith('/employees/')) return { title: 'Hồ Sơ Nhân Viên', sub: 'Xem chi tiết thông tin' };
    if (path === '/employees') return { title: 'Danh Sách Nhân Viên', sub: 'Quản lý toàn bộ nhân viên' };
    if (path === '/departments') return { title: 'Phòng Ban', sub: 'Quản lý cơ cấu phòng ban' };
    if (path === '/positions') return { title: 'Chức Vụ', sub: 'Quản lý chức danh, vị trí' };
    if (path === '/payroll') return { title: 'Bảng Lương Tháng', sub: 'Tổng hợp lương tháng' };
    if (path === '/salary-history') return { title: userRole === 'Employee' ? 'Lương Của Tôi' : 'Lịch Sử Lương', sub: 'Tra cứu lịch sử trả lương' };
    if (path === '/attendance') return { title: 'Dữ Liệu Chấm Công', sub: 'Thống kê ngày công' };
    if (path === '/import-leave') return { title: userRole === 'Employee' ? 'Xin Nghỉ Phép' : 'Import & Nghỉ Phép', sub: userRole === 'Employee' ? 'Nộp đơn xin nghỉ phép' : 'Nhập chấm công & xin nghỉ' };
    if (path === '/reports') return { title: 'Trung Tâm Báo Cáo', sub: 'Báo cáo HR & Payroll' };
    if (path === '/alerts') return { title: 'Cảnh Báo Hệ Thống', sub: 'Sinh nhật, nghỉ quá ngày, bất thường lương' };
    return { title: 'Dashboard', sub: '' };
  };

  // Auto-expand menu khi đang ở trang con
  React.useEffect(() => {
    const path = location.pathname;
    if (path.includes('/employees') || path.includes('/departments') || path.includes('/positions')) {
      setExpandedMenu('hr');
    } else if (path.includes('/payroll') || path.includes('/salary')) {
      setExpandedMenu('payroll');
    } else if (path.includes('/attendance') || path.includes('/import-leave')) {
      setExpandedMenu('attendance');
    }
  }, [location.pathname]);

  const pageTitle = getPageTitle();

  return (
    <div className="d-flex">
      {/* SIDEBAR */}
      <aside className="sidebar">
        <div className="sidebar-brand">
          <div className="brand-icon">X</div>
          <div>
            <h5>Company X</h5>
            <small>HR &amp; Payroll System</small>
          </div>
        </div>

        {/* User info + Role Badge trong sidebar */}
        <div style={{
          margin: '0 12px 16px',
          padding: '12px',
          background: badge.bg,
          borderRadius: 10,
          border: `1px solid ${badge.color}22`
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{
              width: 36, height: 36, borderRadius: 10,
              background: `linear-gradient(135deg, ${badge.color}, ${badge.color}88)`,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: '#fff', fontWeight: 700, fontSize: 13, flexShrink: 0
            }}>
              {userInitials}
            </div>
            <div style={{ overflow: 'hidden' }}>
              <div style={{ fontWeight: 600, fontSize: 13, color: '#1e293b', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {userInfo?.FullName || userInfo?.Username || 'User'}
              </div>
              <div style={{ fontSize: 11, color: badge.color, fontWeight: 600 }}>
                {badge.icon} {badge.label}
              </div>
            </div>
          </div>
        </div>

        <ul className="sidebar-nav">
          {visibleMenus.map((item) => (
            <li className="nav-item" key={item.id}>
              {item.subItems ? (
                // Menu có submenu
                <>
                  <button
                    className="nav-link collapsed-menu"
                    onClick={() => toggleMenu(item.id)}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      width: '100%',
                      backgroundColor: expandedMenu === item.id ? '#f0f4f8' : 'transparent',
                      borderLeft: expandedMenu === item.id ? '3px solid #4f46e5' : 'none',
                      paddingLeft: expandedMenu === item.id ? '12px' : '15px',
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <span className="nav-icon">{item.icon}</span>
                      {item.label}
                    </div>
                    <span style={{
                      fontSize: '12px',
                      transition: 'transform 0.2s',
                      transform: expandedMenu === item.id ? 'rotate(180deg)' : 'rotate(0deg)',
                    }}>▼</span>
                  </button>

                  {expandedMenu === item.id && (
                    <ul className="sidebar-submenu" style={{
                      paddingLeft: '10px',
                      marginTop: '4px',
                      borderLeft: '2px solid #e2e8f0',
                      animation: 'slideDown 0.2s ease-out',
                    }}>
                      {item.subItems.map((subItem) => (
                        <li key={subItem.path}>
                          <NavLink
                            to={subItem.path}
                            end
                            className={({ isActive }) => `nav-link submenu-link ${isActive ? 'active' : ''}`}
                            style={{
                              paddingLeft: '20px',
                              fontSize: '13px',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '6px',
                            }}
                          >
                            <span>{subItem.icon}</span>
                            {subItem.label}
                          </NavLink>
                        </li>
                      ))}
                    </ul>
                  )}
                </>
              ) : (
                // Menu đơn
                <NavLink
                  to={item.path}
                  end={item.path === '/'}
                  className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}
                >
                  <span className="nav-icon">{item.icon}</span>
                  {item.label}
                </NavLink>
              )}
            </li>
          ))}
        </ul>
      </aside>

      {/* MAIN */}
      <div className="main-content flex-grow-1">
        {/* TOP NAVBAR */}
        <div className="top-navbar">
          <div className="page-title">
            {pageTitle.title}
            <small>{pageTitle.sub}</small>
          </div>
          <div className="navbar-actions">
            <button className="btn-icon" title="Thông báo">
              🔔
              {alertCount > 0 && <span className="notification-badge">{alertCount}</span>}
            </button>
            <button className="btn-icon" title="Cài đặt">⚙️</button>
            <div
              className="user-avatar"
              onClick={handleLogout}
              title={`Đăng xuất (${userInfo?.Username || 'admin'})`}
              style={{ cursor: 'pointer' }}
            >
              {userInitials}
            </div>
          </div>
        </div>

        {/* PAGE CONTENT */}
        <div className="page-content">
          <Outlet />
        </div>
      </div>

      <style>{`
        @keyframes slideDown {
          from { opacity: 0; max-height: 0; }
          to   { opacity: 1; max-height: 500px; }
        }
      `}</style>
    </div>
  );
}

export default DashboardLayout;
